export type TicketTier = { name: string; price: number; description: string; available: number };
export type EventItem = {
  id: string;
  title: string;
  category: string;
  date: string;
  time: string;
  location: string;
  venue: string;
  image: string;
  price: number;
  attendees: string;
  remaining: number;
  organizer: string;
  organizerRole: string;
  description: string;
  gradient: string;
  featured?: boolean;
  tickets: TicketTier[];
  paymentUpi?: string;
  paymentWhatsapp?: string;
  ticketTheme?: string;
};
export type Booking = {
  id: string;
  eventId: string;
  eventTitle: string;
  date: string;
  location: string;
  ticket: string;
  quantity: number;
  total: number;
  attendee: string;
  email: string;
  passes?: TicketPass[];
  paymentStatus?: "PENDING" | "PAID";
};
export type TicketPass = {
  passId: string;
  bookingId: string;
  eventId: string;
  status: "ACTIVE" | "CHECKED_IN" | "CANCELLED";
};

